"""Guided onboarding with fictional account data; no real broker or order calls."""
import json,multiprocessing,sys,tempfile,time,urllib.request
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from tools.workbench_browser import serve

def main():
    from playwright.sync_api import sync_playwright,expect
    checks=[];errors=[];base='http://127.0.0.1:8796';headers={'Content-Type':'application/json','X-Artha-Client':'paper-workspace'}
    with tempfile.TemporaryDirectory(prefix='artha-trading-onboarding-',dir=ROOT/'data') as directory:
        process=multiprocessing.get_context('spawn').Process(target=serve,args=(str(Path(directory)/'paper.sqlite3'),True));process.start()
        try:
            for _ in range(100):
                try:urllib.request.urlopen(base+'/api/health',timeout=1).close();break
                except OSError:time.sleep(.1)
            else:raise RuntimeError('Controlled onboarding server did not start')
            with sync_playwright() as pw:
                browser=pw.chromium.launch(headless=True,args=['--no-sandbox']);page=browser.new_page(viewport={'width':1600,'height':1100});page.on('pageerror',lambda e:errors.append(str(e)))
                page.goto(base,wait_until='networkidle');page.locator('[data-view="pilot"]').first.click();expect(page.locator('#live-onboarding-steps button')).to_have_count(4);expect(page.locator('#pilot-reconcile')).to_be_disabled();checks.append('four clearly named stages and an honest sign-in requirement')
                page.request.post(base+'/fixture/login',data='{}',headers=headers);page.reload(wait_until='networkidle');page.locator('#pilot-reconcile').click();expect(page.locator('#pilot-account')).to_have_value('AB1234');expect(page.locator('#live-account-summary')).to_contain_text('10,000.00');checks.append('account ID, permitted product and cash are verified by explicit sync')
                page.evaluate("const b=document.createElement('div');b.textContent='CONTROLLED ONBOARDING FIXTURE · NO REAL MONEY';b.style='position:fixed;bottom:0;right:0;background:#253858;color:white;padding:5px 10px;font-size:10px;z-index:9999';document.body.append(b)")
                page.request.post(base+'/fixture/manual-age',data='{}',headers=headers);page.locator('[data-onboarding-step="2"]').first.click();page.wait_for_function("() => document.querySelector('#live-onboarding-message').textContent.includes('refresh automatically')");expect(page.locator('#live-onboarding-steps button').first).to_have_class('complete');checks.append('completed account checks remain checked after execution freshness expires')
                expect(page.locator('#pilot-budget-mode')).to_have_value('BROKER_FUNDS');expect(page.locator('#pilot-custom-budget')).to_be_hidden();checks.append('new drafts default to broker funds with no required app budgets');page.locator('#pilot-budget-mode').select_option('CUSTOM');page.locator('#pilot-order-count').fill('3')
                page.locator('#live-next-limits').click();expect(page.locator('[data-onboarding-panel="2"]')).to_be_visible();expect(page.locator('#setup-error-capital')).not_to_be_empty();checks.append('blank financial fields receive inline validation without changing stages')
                for key,value in [('symbols','RELIANCE'),('capital','2000'),('loss','100'),('trade-loss','50'),('order-cap','1000'),('expiry','2026-11-06T10:00'),('reviewer','Controlled owner')]:page.locator('#pilot-'+key).fill(value)
                page.locator('#live-next-limits').click();expect(page.locator('[data-onboarding-panel="3"]')).to_be_visible();expect(page.locator('[data-onboarding-panel="3"]')).to_contain_text('read APIs do not expose the whitelist');assert page.locator('[data-onboarding-panel="3"] a[href="https://developers.kite.trade/"]').count()==1;checks.append('broker permission stage provides official links and distinguishes owner confirmation from API verification')
                page.evaluate("window.scrollTo({top:0,left:0,behavior:'instant'})");page.screenshot(path=str(ROOT/'docs/screenshots/trading-onboarding-permissions-controlled.png'),full_page=True)
                page.locator('#live-next-permissions').click();expect(page.locator('[data-onboarding-panel="3"]')).to_be_visible();expect(page.locator('#live-onboarding-message')).to_contain_text('confirm the three');checks.append('unconfirmed external permissions cannot silently pass')
                for key in ['native-stops','static-ip','delivery']:page.locator('#pilot-'+key).check()
                page.request.post(base+'/fixture/manual-loss',data='{"breach":true}',headers=headers);page.locator('#live-next-permissions').click();expect(page.locator('[data-onboarding-panel="4"]')).to_be_visible();expect(page.locator('#live-setup-review')).to_contain_text('checks need attention');expect(page.locator('#live-setup-review [data-status="FAIL"]')).to_contain_text('Daily loss threshold');expect(page.locator('#pilot-save-limits')).to_be_disabled();checks.append('daily-loss validation explains step 8 failure and blocks saving')
                page.evaluate("window.scrollTo({top:0,left:0,behavior:'instant'})");page.screenshot(path=str(ROOT/'docs/screenshots/trading-onboarding-risk-controlled.png'),full_page=True)
                page.request.post(base+'/fixture/manual-loss',data='{"breach":false}',headers=headers);page.locator('#live-validate-setup').click();expect(page.locator('#live-setup-review')).to_contain_text('Setup validation passed');expect(page.locator('#pilot-save-limits')).to_be_enabled();assert page.request.get(base+'/api/pilot/status').json()['mandate'] is None;checks.append('successful validation alone creates no authority and activates nothing')
                page.evaluate("window.scrollTo({top:0,left:0,behavior:'instant'})");page.screenshot(path=str(ROOT/'docs/screenshots/trading-onboarding-review-controlled.png'),full_page=True)
                page.locator('[data-onboarding-step="2"]').first.click();page.locator('#pilot-capital').fill('11000');page.locator('[data-onboarding-step="4"]').first.click();expect(page.locator('#pilot-save-limits')).to_be_disabled();page.locator('#live-validate-setup').click();expect(page.locator('#live-setup-review [data-status="FAIL"]')).to_contain_text('Cash covers your allocation');checks.append('changing allocation invalidates the old review and insufficient cash is explained')
                page.locator('[data-onboarding-step="2"]').first.click();page.locator('#pilot-capital').fill('2000');page.locator('[data-onboarding-step="4"]').first.click();page.locator('#live-validate-setup').click();expect(page.locator('#pilot-save-limits')).to_be_enabled();page.locator('#pilot-manual-confirm').fill('ENABLE MANUAL NSE DELIVERY TRADING');page.locator('#pilot-save-limits').click();expect(page.locator('#pilot-setup-message')).to_contain_text('Trading permissions saved');p=page.request.get(base+'/api/pilot/status').json();assert p['mandate'] and not p['armed'] and not p['orders'];checks.append('explicit save persists limits and consents while keeping the session inactive')
                page.reload(wait_until='networkidle');expect(page.locator('#pilot-capital')).to_have_value('2000');expect(page.locator('#pilot-static-ip')).to_be_checked();expect(page.locator('#pilot-native-stops')).to_be_checked();checks.append('saved limits and owner confirmations rehydrate after browser reload')
                page.locator('[data-onboarding-step="2"]').first.click();expect(page.locator('#pilot-universe')).to_have_value('SELECTED');page.locator('#pilot-universe').select_option('ALL_NSE_EQ');expect(page.locator('#pilot-symbols-field')).to_be_hidden();expect(page.locator('#pilot-capital')).to_have_value('2000');checks.append('all-stocks permission removes the comma list while preserving budget values')
                page.locator('[data-onboarding-step="4"]').first.click();expect(page.locator('#pilot-save-limits')).to_be_disabled();page.locator('#live-validate-setup').click();expect(page.locator('#live-review-summary')).to_contain_text('All supported NSE stocks and ETFs');page.locator('#pilot-manual-confirm').fill('ENABLE MANUAL NSE DELIVERY TRADING');page.locator('#pilot-save-limits').click();expect(page.locator('#pilot-setup-message')).to_contain_text('Trading permissions saved');saved=page.request.get(base+'/api/pilot/status').json();assert saved['mandate']['instrument_scope']=='ALL_NSE_EQ' and saved['mandate']['symbols']==[] and not saved['armed'] and not saved['orders'];checks.append('universe change requires a new review and explicit save without activating trading')
                page.reload(wait_until='networkidle');page.locator('[data-onboarding-step="2"]').first.click();expect(page.locator('#pilot-universe')).to_have_value('ALL_NSE_EQ');expect(page.locator('#pilot-symbols-field')).to_be_hidden();checks.append('all-stocks permission survives reload without expanding older selected permissions')
                page.evaluate("const b=document.createElement('div');b.textContent='CONTROLLED ONBOARDING FIXTURE · NO REAL MONEY';b.style='position:fixed;bottom:0;right:0;background:#253858;color:white;padding:5px 10px;font-size:10px;z-index:9999';document.body.append(b)");page.evaluate("window.scrollTo({top:0,left:0,behavior:'instant'})");page.screenshot(path=str(ROOT/'docs/screenshots/trading-onboarding-all-stocks-controlled.png'),full_page=True)
                page.locator('#pilot-universe').select_option('SELECTED');page.locator('#live-next-limits').click();expect(page.locator('#setup-error-symbols')).to_contain_text('Selected stocks require');expect(page.locator('[data-onboarding-panel="2"]')).to_be_visible();page.locator('#pilot-universe').select_option('ALL_NSE_EQ');checks.append('selected mode still requires an explicit nonempty symbol list')
                page.locator('#pilot-budget-mode').select_option('BROKER_FUNDS');expect(page.locator('#pilot-custom-budget')).to_be_hidden()
                for field in ['pilot-capital','pilot-order-cap','pilot-loss','pilot-trade-loss','pilot-order-count']:assert page.locator('#'+field).get_attribute('max') is None
                page.locator('[data-onboarding-step="4"]').first.click();expect(page.locator('#pilot-save-limits')).to_be_disabled();page.locator('#live-validate-setup').click();expect(page.locator('#live-review-summary')).to_contain_text('Broker funds');expect(page.locator('#live-review-summary')).to_contain_text('No app cap');page.locator('#pilot-manual-confirm').fill('ENABLE MANUAL NSE DELIVERY TRADING');page.locator('#pilot-save-limits').click();expect(page.locator('#pilot-setup-message')).to_contain_text('Trading permissions saved');uncapped=page.request.get(base+'/api/pilot/status').json();assert uncapped['mandate']['limit_mode']=='BROKER_FUNDS' and all(uncapped['mandate'][key] is None for key in ['capital','daily_loss','max_trade_loss','max_order','max_orders_per_day']);assert not uncapped['armed'] and not uncapped['orders'];checks.append('broker-funded mode saves null budgets explicitly and leaves account inactive')
                page.reload(wait_until='networkidle');page.locator('[data-onboarding-step="2"]').first.click();expect(page.locator('#pilot-budget-mode')).to_have_value('BROKER_FUNDS');expect(page.locator('#pilot-custom-budget')).to_be_hidden();expect(page.locator('#pilot-universe')).to_have_value('ALL_NSE_EQ');checks.append('no-cap funding policy and all-stock permission survive reload')
                page.evaluate("const b=document.createElement('div');b.textContent='CONTROLLED BROKER-FUNDED FIXTURE · NO REAL MONEY';b.style='position:fixed;bottom:0;right:0;background:#253858;color:white;padding:5px 10px;font-size:10px;z-index:9999';document.body.append(b)");page.evaluate("window.scrollTo({top:0,left:0,behavior:'instant'})");page.screenshot(path=str(ROOT/'docs/screenshots/trading-onboarding-broker-funded-controlled.png'),full_page=True)
                page.set_viewport_size({'width':390,'height':844});page.locator('[data-onboarding-step="3"]').first.click();assert page.evaluate('document.documentElement.scrollWidth<=innerWidth+2');page.evaluate("window.scrollTo({top:0,left:0,behavior:'instant'})");page.screenshot(path=str(ROOT/'docs/screenshots/trading-onboarding-mobile-controlled.png'),full_page=True);checks.append('guided permissions and navigation remain usable on mobile')
                assert not errors,errors;browser.close()
        finally:process.terminate();process.join(15)
    record=dict(passed=len(checks),checks=checks,javascript_errors=errors,controlled_broker=True,real_broker_reads=False,real_orders_sent=False,private_account_artifacts_created=False)
    (ROOT/'docs/trading-onboarding-browser-validation.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record))
if __name__=='__main__':main()
